let idCounter = 1;

class ObjectId {
  constructor(idStr) {
    if (idStr) {
      this.id = typeof idStr === 'object' && idStr.id ? idStr.id : idStr.toString();
    } else {
      const hex = (Date.now().toString(16) + (idCounter++).toString(16)).padStart(24, '0');
      this.id = hex.slice(-24);
    }
  }
  toString() {
    return this.id;
  }
  toJSON() {
    return this.id;
  }
  equals(other) {
    if (!other) return false;
    return this.toString() === (other.id || other.toString());
  }
}

class Schema {
  constructor(definition = {}, options = {}) {
    this.definition = definition;
    this.options = options;
    this.methods = {};
    this.virtuals = {};
    this.paths = {};
    this._flattenPaths(definition, '');
  }

  _flattenPaths(def, prefix) {
    for (const key in def) {
      const fullPath = prefix ? `${prefix}.${key}` : key;
      const val = def[key];
      if (val && typeof val === 'object' && !val.type && !Array.isArray(val)) {
        this._flattenPaths(val, fullPath);
      } else {
        const defaultValue = (val && typeof val === 'object' && val.default !== undefined) ? val.default : undefined;
        this.paths[fullPath] = { defaultValue, type: val };
      }
    }
  }

  virtual(name) {
    const self = this;
    return {
      get(fn) {
        self.virtuals[name] = fn;
        return this;
      }
    };
  }

  path(pathName) {
    return this.paths[pathName] || { defaultValue: undefined };
  }
}

Schema.Types = {
  ObjectId: ObjectId,
  String: String,
  Number: Number,
  Boolean: Boolean,
  Date: Date
};

const collections = {};

function matchesQuery(doc, query) {
  if (!query || Object.keys(query).length === 0) return true;
  for (const key in query) {
    const queryVal = query[key];
    const docVal = getNestedValue(doc, key);

    if (queryVal && typeof queryVal === 'object' && !Array.isArray(queryVal) && !(queryVal instanceof Date) && !(queryVal instanceof ObjectId)) {
      if (queryVal.$lt !== undefined && !(docVal < queryVal.$lt)) return false;
      if (queryVal.$gt !== undefined && !(docVal > queryVal.$gt)) return false;
      if (queryVal.$lte !== undefined && !(docVal <= queryVal.$lte)) return false;
      if (queryVal.$gte !== undefined && !(docVal >= queryVal.$gte)) return false;
      if (queryVal.$ne !== undefined && docVal === queryVal.$ne) return false;
    } else {
      const qStr = queryVal !== undefined && queryVal !== null ? queryVal.toString() : '';
      const dStr = docVal !== undefined && docVal !== null ? docVal.toString() : '';
      if (qStr !== dStr) return false;
    }
  }
  return true;
}

function getNestedValue(obj, path) {
  if (!obj) return undefined;
  const parts = path.split('.');
  let curr = obj;
  for (const p of parts) {
    if (curr === undefined || curr === null) return undefined;
    curr = curr[p];
  }
  return curr;
}

function setNestedValue(obj, path, value) {
  const parts = path.split('.');
  let curr = obj;
  for (let i = 0; i < parts.length - 1; i++) {
    const p = parts[i];
    if (!curr[p] || typeof curr[p] !== 'object') {
      curr[p] = {};
    }
    curr = curr[p];
  }
  curr[parts[parts.length - 1]] = value;
}

function applyDefaults(def, data, doc, prefix = '') {
  for (const key in def) {
    const fieldDef = def[key];
    const fullPath = prefix ? `${prefix}.${key}` : key;

    if (fieldDef && typeof fieldDef === 'object' && !fieldDef.type && !Array.isArray(fieldDef)) {
      if (!doc[key]) doc[key] = {};
      applyDefaults(fieldDef, data && data[key] ? data[key] : {}, doc[key], fullPath);
    } else {
      let val = data ? data[key] : undefined;
      if (val === undefined && fieldDef && typeof fieldDef === 'object' && fieldDef.default !== undefined) {
        val = typeof fieldDef.default === 'function' ? fieldDef.default() : fieldDef.default;
      }
      if (val !== undefined) {
        doc[key] = val;
      }
    }
  }
}

function deepClonePlain(val) {
  if (val === null || val === undefined) return val;
  if (val instanceof ObjectId) return val.toString();
  if (val instanceof Date) return val;
  if (Array.isArray(val)) return val.map(deepClonePlain);
  if (typeof val === 'object') {
    const obj = {};
    for (const k in val) {
      if (typeof val[k] !== 'function') {
        obj[k] = deepClonePlain(val[k]);
      }
    }
    return obj;
  }
  return val;
}

function createModel(modelName, schema) {
  if (!collections[modelName]) {
    collections[modelName] = [];
  }

  class Model {
    constructor(data = {}) {
      this._id = data._id ? new ObjectId(data._id) : new ObjectId();
      
      // Bind schema methods
      for (const methodName in schema.methods) {
        this[methodName] = schema.methods[methodName].bind(this);
      }

      // Apply schema defaults & assign data properties
      applyDefaults(schema.definition, data, this);
      Object.assign(this, data);
      this._id = this._id ? new ObjectId(this._id) : new ObjectId();
    }

    async save() {
      const store = collections[modelName];
      const now = new Date();
      if (schema.options && schema.options.timestamps) {
        if (!this.createdAt) this.createdAt = now;
        this.updatedAt = now;
      }
      const existingIdx = store.findIndex(d => d._id.toString() === this._id.toString());
      if (existingIdx >= 0) {
        store[existingIdx] = this;
      } else {
        store.push(this);
      }
      return this;
    }

    toObject(options = {}) {
      const plain = {};
      for (const key in this) {
        if (typeof this[key] !== 'function') {
          plain[key] = deepClonePlain(this[key]);
        }
      }
      plain._id = this._id ? this._id.toString() : plain._id;
      
      // Evaluate virtual getters if requested
      if (options && options.virtuals) {
        for (const vName in schema.virtuals) {
          plain[vName] = schema.virtuals[vName].call(this);
        }
      }
      return plain;
    }

    toJSON(options = {}) {
      return this.toObject(options);
    }

    static async find(query = {}) {
      const store = collections[modelName];
      const matched = store.filter(doc => matchesQuery(doc, query));
      return matched;
    }

    static async findById(id) {
      if (!id) return null;
      const store = collections[modelName];
      const doc = store.find(d => d._id.toString() === id.toString());
      return doc || null;
    }

    static async findOne(query = {}) {
      const store = collections[modelName];
      const doc = store.find(d => matchesQuery(d, query));
      return doc || null;
    }

    static async findByIdAndUpdate(id, update = {}, options = {}) {
      const doc = await Model.findById(id);
      if (!doc) return null;

      const updateData = update.$set ? update.$set : update;
      for (const key in updateData) {
        if (key !== '_id') {
          setNestedValue(doc, key, updateData[key]);
        }
      }
      if (schema.options && schema.options.timestamps) {
        doc.updatedAt = new Date();
      }
      await doc.save();
      return doc;
    }

    static async findByIdAndDelete(id) {
      const store = collections[modelName];
      const idx = store.findIndex(d => d._id.toString() === id.toString());
      if (idx >= 0) {
        const [deleted] = store.splice(idx, 1);
        return deleted;
      }
      return null;
    }

    static async deleteMany(query = {}) {
      const store = collections[modelName];
      const toDelete = store.filter(d => matchesQuery(d, query));
      collections[modelName] = store.filter(d => !matchesQuery(d, query));
      return { deletedCount: toDelete.length };
    }
  }

  Model.schema = schema;
  Model.modelName = modelName;
  return Model;
}

const connection = {
  readyState: 1,
  collections: collections,
  async disconnect() {
    this.readyState = 0;
    for (const k in collections) {
      collections[k] = [];
    }
  }
};

module.exports = {
  Schema,
  Types: { ObjectId },
  model: createModel,
  connect: async (uri) => {
    connection.readyState = 1;
    return connection;
  },
  disconnect: async () => {
    return connection.disconnect();
  },
  connection
};
